            seen[r][c] = True
            cells = []
            wall_edges = 0

            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nx, ny = x + dx, y + dy
                    if not (0 <= nx < h and 0 <= ny < w):
                        continue
                    if grid[nx][ny] == bg:
                        if not seen[nx][ny]:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                    else:
                        wall_edges += 1

            # Fill small pockets enclosed by the line pattern. Some pockets
            # are closed partly by the edge of the grid.
            if len(cells) <= 20 and wall_edges >= len(cells):
                for x, y in cells:
                    out[x][y] = 4

    return out
